 async function actualScroll(selector,gid){await page.$eval(selector,f=>f.contentWindow.scrollTo(0,f.contentDocument.querySelector('.sc').offsetHeight/2-f.contentWindow.innerHeight/2));await page.waitForFunction(({selector,gid})=>document.querySelector(selector).contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()>.4,{},{selector,gid});const result=await page.$eval(selector,(f,gid)=>({p:f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress(),phase:+f.contentDocument.querySelector('[data-nw-stream-slot]').dataset.nwStreamPhase}),gid);assert.ok(Math.abs(result.phase-(result.p*100-20)/60*3)<.001);await page.$eval(selector,f=>f.contentWindow.scrollTo(0,0));await page.waitForFunction(({selector,gid})=>document.querySelector(selector).contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()<.05,{},{selector,gid});}
