 function screenshotPixel(bytes){const png=Buffer.from(bytes),chunks=[];let channels;for(let i=8;i<png.length;){const length=png.readUInt32BE(i),kind=png.subarray(i+4,i+8).toString(),data=png.subarray(i+8,i+8+length);if(kind==='IHDR'){assert.equal(data.readUInt32BE(0),1);assert.equal(data.readUInt32BE(4),1);assert.equal(data[8],8);channels=data[9]===2?3:4;}if(kind==='IDAT')chunks.push(data);i+=length+12;}return Array.from(inflateSync(Buffer.concat(chunks)).subarray(1,1+channels)).concat(channels===3?[255]:[]);}
