  await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="spiral-stream"]');await ready();assert.equal(await page.$eval('[data-motion-config="duration"]',n=>n.value),'28');assert.equal(await page.$eval('[data-motion-stream-count]',n=>[n.min,n.max].join(',')),'6,20');for(const [key,expected] of [['spiralTurns','3.75,1,6,0.25'],['cardCount','24,8,48,1'],['taper','0,-90,90,5'],['cardSize','33,12,36,1'],['gap','28,0,50,2']])assert.equal(await page.$eval('[data-motion-stream="'+key+'"]',n=>[n.value,n.min,n.max,n.step].join(',')),expected);
