  await change('[data-motion-stream-count]','6',6);await page.click('[data-motion-library-tab="elements"]');await page.click('[data-motion-layer="'+start[0].id+'"]');assert.equal(await page.$eval('[data-motion-element-remove]',n=>n.disabled),true);await change('[data-motion-stream-count]','20',20);await change('[data-motion-stream-count]','12');assert.deepEqual((await pose(0)).map(n=>[n.id,n.src]),start.map(n=>[n.id,n.src]));
  // Solid images expose the real overlap and per-strip depth in the screenshot and pointer picker.
  const colors=Array.from({length:12},(_,i)=>[(i&1)?255:40,(i&2)?255:40,(i&4)?255:40]);
  for(const [key,value] of [['spiralTurns','6'],['cardCount','48'],['taper','0'],['tilt','0'],['perspective','20'],['scalePulse','0'],['ringSize','62'],['gap','0'],['cardSize','36'],['cornerRadius','0'],['shadow',false],['frameRatio','auto']])await change('[data-motion-stream="'+key+'"]',value);
  await page.$eval('[data-motion-stream-batch-upload]',(input,colors)=>{const transfer=new DataTransfer();colors.forEach((color,i)=>transfer.items.add(new File(['<svg xmlns="http://www.w3.org/2000/svg" width="300" height="300"><rect width="300" height="300" fill="rgb('+color.join(',')+')"/></svg>'],'Spiral-'+i+'.svg',{type:'image/svg+xml'})));input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));},colors);await page.waitForFunction(()=>/Se cargaron 12/.test(document.querySelector('[data-motion-stream-batch-status]')?.textContent||''));await ready();
  for(const cardStyle of ['curved','upright']){await change('[data-motion-stream="cardStyle"]',cardStyle);const probe=await page.$eval('.nw-motion-dialog iframe',(f,colors)=>{const d=f.contentDocument,nodes=Array.from(d.querySelectorAll('[data-nw-stream-slot]')),host=nodes[0].offsetParent,inside=(poly,x,y)=>{let hit=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++)if((poly[i].y>y)!==(poly[j].y>y)&&x<(poly[j].x-poly[i].x)*(y-poly[i].y)/(poly[j].y-poly[i].y)+poly[i].x)hit=!hit;return hit;};for(const progress of [.07,.17,.33,.61]){f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id].set(progress);const clip=nodes[0].__nwMotionClip,tiles=nodes.flatMap((n,slot)=>n.__nwMotionInstances.flatMap(t=>t.stripDepth.map((depth,i)=>({id:n.dataset.id,slot,index:t.index,alpha:t.alpha,depth,polygon:[t.upper[i],t.upper[i+1],t.lower[i+1],t.lower[i]]}))));for(let y=clip.top+20;y<clip.top+clip.height-20;y+=9)for(let x=clip.left+20;x<clip.left+clip.width-20;x+=9){const hits=tiles.filter(t=>inside(t.polygon,x,y)).sort((a,b)=>b.depth-a.depth);if(new Set(hits.map(t=>t.index)).size<2||hits[0].alpha!==1)continue;const top=hits[0];if([-3,3].some(dx=>[-3,3].some(dy=>tiles.filter(t=>inside(t.polygon,x+dx,y+dy)).sort((a,b)=>b.depth-a.depth)[0]?.id!==top.id)))continue;const fr=f.getBoundingClientRect(),hr=host.getBoundingClientRect();return{id:top.id,expected:colors[top.slot],click:{x:fr.left+(hr.left+x)*fr.width/f.clientWidth,y:fr.top+(hr.top+y)*fr.height/f.clientHeight}};}}return null;},colors);assert.ok(probe,'Spiral has visible depth overlaps in '+cardStyle);const pixel=screenshotPixel(await page.screenshot({type:'png',clip:{x:Math.floor(probe.click.x),y:Math.floor(probe.click.y),width:1,height:1}}));for(let i=0;i<3;i++)assert.ok(Math.abs(pixel[i]-probe.expected[i])<5,JSON.stringify({cardStyle,probe,pixel}));await page.mouse.click(probe.click.x,probe.click.y);assert.equal(await page.$eval('[data-motion-layer="'+probe.id+'"]',n=>n.getAttribute('aria-pressed')),'true');}
